#[path="../source_holes.rs"]mod source_holes;
#[path="../owner_registry.rs"]mod owner_registry;#[path="../owner_budget.rs"]mod owner_budget;#[path="../journal.rs"]mod journal;#[path="../owner.rs"]mod owner;#[path="../face_owner.rs"]mod face_owner;
use ingetrazo_core::mesh::Mesh;use glam::DVec3;use serde_json::json;
fn state(o:&face_owner::FaceOwner,name:&str)->serde_json::Value{let m=o.mesh();json!({"name":name,"undo":o.history_counts().0,"redo":o.history_counts().1,"adjacency":m.vertices.iter().map(|v|{let mut e=v.edges.clone();e.sort_unstable();e}).collect::<Vec<_>>(),"vertices":m.vertices.iter().map(|v|v.position.to_array()).collect::<Vec<_>>(),"edges":m.edges.iter().map(|e|json!({"vertices":[e.v0,e.v1],"faces":e.faces})).collect::<Vec<_>>(),"faces":m.faces.iter().map(|f|json!({"outer":f.vertices,"holes":f.holes})).collect::<Vec<_>>()})}
fn main(){let cases:serde_json::Value=serde_json::from_str(include_str!("../../face-multiple-hole-cases.json")).unwrap();let mut results=vec![];for case in cases.as_array().unwrap(){let mut o=face_owner::FaceOwner::new(Mesh::new()).unwrap();let point=|p:&serde_json::Value|DVec3::new(p[0].as_f64().unwrap(),p[1].as_f64().unwrap(),p[2].as_f64().unwrap());let outer:Vec<_>=case["outer"].as_array().unwrap().iter().map(point).collect();let holes:Vec<Vec<_>>=case["holes"].as_array().unwrap().iter().map(|h|h.as_array().unwrap().iter().map(point).collect()).collect();let name=case["name"].as_str().unwrap();let mut t=o.begin().unwrap();t.add_face(&outer,&holes).unwrap();o.commit(t).unwrap();results.push(state(&o,name));let saved=o.mesh().clone();o.undo().unwrap();results.push(state(&o,&format!("{name}-undo")));o.redo().unwrap();assert_eq!(o.mesh(),&saved);results.push(state(&o,&format!("{name}-redo")));}println!("{}",serde_json::to_string_pretty(&results).unwrap());}